// Flag post that lights up once reached; the GameManager stores the position.
defineScript({
  name: 'Checkpoint',
  description: 'Respawn point shared by every player.',
  onMessage(ctx, name) {
    const sprite = ctx.get('Sprite');
    if (!sprite) return;
    if (name === 'activate') { sprite.tint.setHex('#06d6a0'); ctx.state.active = true; }
    else if (name === 'reset') { sprite.tint.setHex('#ffffff'); ctx.state.active = false; }
  },
  onUpdate(ctx) {
    if (!ctx.state.active) return;
    const sprite = ctx.get('Sprite');
    if (sprite) sprite.alpha = 0.85 + Math.sin(ctx.time.elapsed * 6) * 0.15;
  },
});

// Bobbing, spinning coin. Collected by a "collect" message from a player.
defineScript({
  name: 'Coin',
  description: 'Collectible coin.',
  props: { bob: { type: 'number', default: 0.12, min: 0, max: 1 } },
  onStart(ctx) {
    ctx.state.baseY = ctx.transform.y;
    ctx.state.phase = (ctx.transform.x * 0.7) % (Math.PI * 2);
    ctx.state.taken = false;
  },
  onUpdate(ctx) {
    const t = ctx.time.elapsed + ctx.state.phase;
    ctx.transform.y = ctx.state.baseY + Math.sin(t * 3) * ctx.props.bob;
    const sprite = ctx.get('Sprite');
    if (sprite) sprite.width = 0.6 * Math.abs(Math.cos(t * 2.5)) + 0.05;
  },
  onMessage(ctx, name, data) {
    if (name !== 'collect' || ctx.state.taken || !ctx.net.isHost) return;
    ctx.state.taken = true;
    ctx.audio.play('sfx-coin', { volume: 0.5, pitchVariation: 0.05 });
    const em = ctx.get('ParticleEmitter');
    if (em) em.burst(10);
    const sprite = ctx.get('Sprite');
    if (sprite) sprite.visible = false;
    ctx.send('coinCollected', { by: data && data.by });
    const sync = ctx.net.hub.sync;
    ctx.timer(0.4, () => { if (sync) sync.despawn(ctx.entity); else ctx.destroy(); });
  },
});

// Co-op level flow: spawns a Hopper per player, counts coins, remembers the
// shared checkpoint, handles respawns and the level-complete screen.
function hud(ctx) { return ctx.engine.canvas ? ctx.engine.hud : null; }

const COLORS = ['#4cc2ff', '#ff7a3d', '#8b7dff', '#06d6a0'];

defineScript({
  name: 'GameManager',
  description: 'Spawns players, tracks coins/checkpoints, restarts the level.',
  props: {
    respawnDelay: { type: 'number', default: 1, min: 0, max: 10 },
    restartDelay: { type: 'number', default: 5, min: 1, max: 30 },
    spawnName: { type: 'string', default: 'Spawn Point' },
  },
  onStart(ctx) {
    const s = ctx.state;
    s.players = {};
    s.count = 0;
    s.unsub = [];
    s.coins = 0;
    s.startTime = ctx.time.elapsed;
    s.complete = false;
    const spawn = ctx.find(ctx.props.spawnName);
    const st = spawn !== undefined ? ctx.getOn(spawn, 'Transform') : null;
    s.spawn = st ? { x: st.x, y: st.y } : { x: 2, y: 3 };
    s.checkpoint = { ...s.spawn };
    // Remember every coin so the level can be rebuilt after completion.
    s.coinSpots = ctx.findAll('coin').map((e) => { const t = ctx.getOn(e, 'Transform'); return { x: t.x, y: t.y }; });
    s.totalCoins = s.coinSpots.length;

    if (ctx.net.isHost) {
      this.addPlayer(ctx, ctx.net.localId);
      const sync = ctx.net.hub.sync;
      if (sync) {
        for (const p of sync.players()) if (p.peerId !== ctx.net.localId) this.addPlayer(ctx, p.peerId);
        s.unsub.push(sync.on('playerJoined', ({ peerId }) => { this.addPlayer(ctx, peerId); this.resendHud(ctx); }));
        s.unsub.push(sync.on('playerLeft', ({ peerId }) => this.removePlayer(ctx, peerId)));
      }
    }
    this.drawHud(ctx);
  },
  onDestroy(ctx) {
    for (const off of ctx.state.unsub) off();
    const h = hud(ctx);
    if (h) { h.remove('coins'); h.remove('hint'); h.remove('complete'); }
  },
  onUpdate(ctx) {
    if (ctx.time.frame % 20 === 0) this.drawHud(ctx);
  },

  addPlayer(ctx, peerId) {
    const s = ctx.state;
    if (s.players[peerId]) return;
    const index = s.count++;
    const pos = { x: s.checkpoint.x + (index % 4) * 0.6, y: s.checkpoint.y };
    const entity = ctx.net.spawn('Hopper', { ownerId: peerId, position: pos });
    const pi = ctx.getOn(entity, 'PlayerInput');
    if (pi) pi.owner = peerId;
    const ni = ctx.getOn(entity, 'NetworkIdentity');
    if (ni) ni.ownerId = peerId;
    const name = ctx.getOn(entity, 'Name');
    if (name) name.name = `Hopper ${peerId}`;
    const script = ctx.getOn(entity, 'Script');
    script.props.color = COLORS[index % COLORS.length];
    script.props.label = `P${index + 1}`;
    script.props.respawnDelay = ctx.props.respawnDelay;
    s.players[peerId] = { entity, index };
  },
  removePlayer(ctx, peerId) {
    const p = ctx.state.players[peerId];
    if (!p) return;
    if (ctx.world.isAlive(p.entity)) {
      const sync = ctx.net.hub.sync;
      if (sync) sync.despawn(p.entity); else ctx.destroy(p.entity);
    }
    delete ctx.state.players[peerId];
  },

  onMessage(ctx, name, data) {
    const s = ctx.state;
    if (!ctx.net.isHost) return;
    if (name === 'coinCollected') { s.coins++; this.drawHud(ctx); }
    else if (name === 'checkpoint') {
      if (data.x > s.checkpoint.x) { s.checkpoint = { x: data.x, y: data.y }; ctx.audio.play('sfx-checkpoint', { volume: 0.6 }); ctx.sendTo(data.entity, 'activate'); }
    }
    else if (name === 'respawnRequest') {
      const t = ctx.getOn(data.entity, 'Transform');
      if (t) t.setPosition(s.checkpoint.x, s.checkpoint.y + 0.5);
      ctx.sendTo(data.entity, 'respawned');
    }
    else if (name === 'goal' && !s.complete) this.complete(ctx);
  },
  complete(ctx) {
    const s = ctx.state;
    s.complete = true;
    const secs = (ctx.time.elapsed - s.startTime).toFixed(1);
    s.done = `Coins ${s.coins} / ${s.totalCoins} · ${secs}s\nRestarting in ${ctx.props.restartDelay}s`;
    const h = hud(ctx);
    if (h) h.panel('complete', 'Level complete!', s.done);
    ctx.audio.play('goal', { volume: 0.8 });
    ctx.send('levelComplete', {});
    this.drawHud(ctx);
    ctx.timer(ctx.props.restartDelay, () => this.restart(ctx));
  },
  restart(ctx) {
    const s = ctx.state;
    for (const c of ctx.findAll('coin')) ctx.destroy(c);
    for (const spot of s.coinSpots) ctx.net.spawn('Coin', { position: spot });
    for (const c of ctx.findAll('checkpoint')) ctx.sendTo(c, 'reset');
    s.coins = 0;
    s.checkpoint = { ...s.spawn };
    s.startTime = ctx.time.elapsed;
    s.complete = false;
    s.done = null;
    for (const p of Object.values(s.players)) {
      const t = ctx.getOn(p.entity, 'Transform');
      if (t) t.setPosition(s.spawn.x + (p.index % 4) * 0.6, s.spawn.y);
      ctx.sendTo(p.entity, 'respawned');
    }
    const h = hud(ctx);
    if (h) h.remove('complete');
    this.drawHud(ctx);
  },

  /** Host → clients: the HUD state travels as an RPC on this entity so guests see the same scoreboard. */
  broadcastHud(ctx, payload) {
    if (!ctx.net.isHost || !ctx.net.online) return;
    const json = JSON.stringify(payload);
    if (json === ctx.state.lastHud) return;
    ctx.state.lastHud = json;
    ctx.net.rpc('hud', [payload], 'others');
  },
  /** Force the next broadcast (a newcomer needs the current state even if nothing changed). */
  resendHud(ctx) { ctx.state.lastHud = null; this.drawHud(ctx); },
  onRpc(ctx, name, args) {
    if (name !== 'hud' || ctx.net.isHost) return;
    const d = args[0];
    const s = ctx.state;
    s.coins = d.coins;
    s.totalCoins = d.totalCoins;
    if (Math.abs((ctx.time.elapsed - s.startTime) - d.secs) > 1.5) s.startTime = ctx.time.elapsed - d.secs;
    s.complete = d.complete;
    const h = hud(ctx);
    if (h) { if (d.done) h.panel('complete', 'Level complete!', d.done); else h.remove('complete'); }
    this.drawHud(ctx);
  },
  drawHud(ctx) {
    const s = ctx.state;
    const secs = Math.floor(ctx.time.elapsed - s.startTime);
    this.broadcastHud(ctx, { coins: s.coins, totalCoins: s.totalCoins, secs, complete: s.complete, done: s.done || null });
    const h = hud(ctx);
    if (!h) return;
    h.text('coins', `Coins ${s.coins} / ${s.totalCoins}   ${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, '0')}`, { anchor: 'top-left' });
    h.text('hint', 'Reach the flag together · A/D move · Space jump', { anchor: 'top' });
  },
});

// The level exit: waves gently; players touching it complete the level.
defineScript({
  name: 'Goal',
  description: 'Level goal flag.',
  onUpdate(ctx) {
    const sprite = ctx.get('Sprite');
    if (sprite) sprite.width = 1 + Math.sin(ctx.time.elapsed * 4) * 0.06;
  },
});

// Kinematic platform oscillating around its start position. Players riding
// it are carried by the Player script (it reads this body's velocity).
defineScript({
  name: 'MovingPlatform',
  description: 'Sinusoidal kinematic platform.',
  props: {
    dx: { type: 'number', default: 0, label: 'Horizontal travel' },
    dy: { type: 'number', default: 3, label: 'Vertical travel' },
    period: { type: 'number', default: 4, min: 0.5, max: 30, label: 'Seconds per cycle' },
    phase: { type: 'number', default: 0, min: 0, max: 6.283 },
  },
  onStart(ctx) {
    ctx.state.origin = { x: ctx.transform.x, y: ctx.transform.y };
    ctx.state.t = ctx.props.phase;
  },
  onFixedUpdate(ctx, dt) {
    const s = ctx.state;
    const w = (Math.PI * 2) / ctx.props.period;
    s.t += dt;
    // Set velocity so the physics step moves the body and contacts feel it.
    const vx = Math.cos(s.t * w) * w * ctx.props.dx * 0.5;
    const vy = Math.cos(s.t * w) * w * ctx.props.dy * 0.5;
    ctx.get('RigidBody2D').setVelocity(vx, vy);
  },
});

// Invisible camera target that sits at the average position of every living
// player, so a following Camera2D frames the whole team.
defineScript({
  name: 'MultiFollow',
  description: 'Averages the positions of tagged entities.',
  props: {
    tag: { type: 'string', default: 'player' },
    lookAhead: { type: 'number', default: 0.6, min: 0, max: 5, label: 'Look-ahead per unit of velocity' },
  },
  onUpdate(ctx) {
    let x = 0, y = 0, n = 0;
    for (const e of ctx.findAll(ctx.props.tag)) {
      const t = ctx.getOn(e, 'Transform');
      const sprite = ctx.getOn(e, 'Sprite');
      if (sprite && !sprite.visible) continue;
      const rb = ctx.getOn(e, 'RigidBody2D');
      x += t.x + (rb ? rb.velocity.x * ctx.props.lookAhead * 0.1 : 0);
      y += t.y;
      n++;
    }
    if (n > 0) ctx.transform.setPosition(x / n, y / n);
  },
});

// Repeating background layer. Children are tiles of width `tileWidth`; the
// root moves at `factor` of the camera speed and re-tiles around the camera.
defineScript({
  name: 'Parallax',
  description: 'Scrolls child sprites slower than the camera.',
  props: {
    factor: { type: 'number', default: 0.7, min: 0, max: 1, label: 'Camera speed fraction' },
    factorY: { type: 'number', default: 0.2, min: 0, max: 1 },
    tileWidth: { type: 'number', default: 32, min: 1 },
    baseY: { type: 'number', default: 9 },
  },
  onLateUpdate(ctx) {
    const cam = ctx.find('Camera');
    if (cam === undefined) return;
    const ct = ctx.getOn(cam, 'Transform');
    const w = ctx.props.tileWidth;
    const rootX = ct.x * ctx.props.factor;
    ctx.transform.setPosition(rootX, ctx.props.baseY + ct.y * ctx.props.factorY);
    const children = ctx.world.getChildren(ctx.entity);
    const center = Math.round((ct.x - rootX) / w) * w;
    children.forEach((child, i) => {
      const t = ctx.getOn(child, 'Transform');
      t.setPosition(center + (i - (children.length - 1) / 2) * w, t.y);
    });
  },
});

// Platformer character. Movement goes through CharacterController2D; coins,
// spikes, checkpoints and the goal are triggers identified by tag.
defineScript({
  name: 'Player',
  description: 'Co-op platformer hero.',
  props: {
    speed: { type: 'number', default: 7.5, min: 1, max: 20 },
    jump: { type: 'number', default: 14.5, min: 1, max: 40 },
    fallLimit: { type: 'number', default: -3, label: 'Y below which the player dies' },
    respawnDelay: { type: 'number', default: 1 },
    color: { type: 'string', default: '#4cc2ff', label: 'Colour (hex)' },
    label: { type: 'string', default: 'P1' },
  },
  onStart(ctx) {
    const cc = ctx.get('CharacterController2D');
    cc.moveSpeed = ctx.props.speed;
    cc.jumpSpeed = ctx.props.jump;
    ctx.state.dead = false;
    ctx.state.wasGrounded = true;
    this.applyLook(ctx);
  },
  onReload(ctx) { this.applyLook(ctx); },
  applyLook(ctx) {
    const sprite = ctx.get('Sprite');
    if (sprite) sprite.tint.setHex(ctx.props.color);
    const plate = ctx.world.getChildren(ctx.entity)[0];
    const text = plate !== undefined ? ctx.getOn(plate, 'Text') : null;
    if (text) { text.text = ctx.props.label; text.color.setHex(ctx.props.color); }
  },

  onOwnerInput(ctx, snap) {
    if (ctx.state.dead) return;
    const cc = ctx.get('CharacterController2D');
    cc.move(snap.axes.moveX || 0);
    if (snap.pressed.includes('jump')) {
      cc.jump();
      if (cc.grounded) ctx.audio.play('jump', { volume: 0.35, pitchVariation: 0.08 });
    }
    if (snap.released.includes('jump')) cc.jumpReleased();
    const sprite = ctx.get('Sprite');
    if (sprite) sprite.flipX = cc.facing < 0;
  },
  onFixedUpdate(ctx, dt) {
    if (ctx.state.dead) return;
    const rb = ctx.get('RigidBody2D');
    const cc = ctx.get('CharacterController2D');
    // Ride kinematic platforms: carry the position by the platform's velocity.
    for (const c of rb.contacts) {
      if (c.ny <= 0.5) continue;
      const other = ctx.getOn(c.other, 'RigidBody2D');
      if (other && other.bodyType === 'kinematic') ctx.transform.translate(other.velocity.x * dt, other.velocity.y * dt);
    }
    // Squash and stretch.
    const sprite = ctx.get('Sprite');
    if (sprite) {
      const vy = rb.velocity.y;
      const target = cc.grounded ? 1 : 1 + ctx.math.clamp(Math.abs(vy) * 0.02, 0, 0.25);
      sprite.height = ctx.math.damp(sprite.height, 1.1 * target, 12, dt);
      sprite.width = ctx.math.damp(sprite.width, 0.9 / target, 12, dt);
    }
    if (cc.grounded && !ctx.state.wasGrounded && rb.velocity.y <= 0.01) {
      const em = ctx.get('ParticleEmitter');
      if (em) em.burst(6);
    }
    ctx.state.wasGrounded = cc.grounded;
    if (ctx.transform.y < ctx.props.fallLimit) this.die(ctx);
  },
  onTriggerEnter(ctx, other) {
    if (!ctx.net.isHost || ctx.state.dead) return;
    const tag = ctx.getOn(other, 'Tag');
    if (!tag) return;
    const me = ctx.net.owner();
    if (tag.has('coin')) ctx.sendTo(other, 'collect', { by: me });
    else if (tag.has('hazard')) this.die(ctx);
    else if (tag.has('checkpoint')) { const t = ctx.getOn(other, 'Transform'); ctx.send('checkpoint', { x: t.x, y: t.y, entity: other }); }
    else if (tag.has('goal')) ctx.send('goal', { by: me });
  },
  die(ctx) {
    if (!ctx.net.isHost || ctx.state.dead) return;
    ctx.state.dead = true;
    const em = ctx.get('ParticleEmitter');
    if (em) em.burst(24);
    ctx.audio.play('hit', { volume: 0.7 });
    const cam = ctx.find('Camera');
    const c = cam !== undefined ? ctx.getOn(cam, 'Camera2D') : null;
    if (c) c.shake = 0.25;
    const rb = ctx.get('RigidBody2D');
    rb.setVelocity(0, 0);
    rb.bodyType = 'kinematic';
    const sprite = ctx.get('Sprite');
    if (sprite) sprite.visible = false;
    ctx.timer(ctx.props.respawnDelay, () => ctx.send('respawnRequest', { entity: ctx.entity }));
  },
  onMessage(ctx, name) {
    if (name !== 'respawned') return;
    const rb = ctx.get('RigidBody2D');
    rb.bodyType = 'dynamic';
    rb.setVelocity(0, 0);
    const sprite = ctx.get('Sprite');
    if (sprite) sprite.visible = true;
    ctx.state.dead = false;
  },
});
